//#region src/components/tailwind/utils/css/separate-adjacent-closing-braces.ts
/**
* A css-tree `generate` decorator that writes `} }` instead of `}}`.
*
* Outlook.com drops everything in a <style> after two adjacent closing braces,
* see https://github.com/hteumeuleu/email-bugs/issues/92. Working on tokens
* instead of the generated string keeps braces inside strings and url() as is.
*/
function separateAdjacentClosingBraces(handlers) {
	const { emit } = handlers;
	let previousValue = "";
	return {
		...handlers,
		emit(value, type, auto) {
			if (value === "}" && previousValue === "}") emit(" ", type, true);
			emit(value, type, auto);
			previousValue = value;
		}
	};
}
//#endregion
exports.separateAdjacentClosingBraces = separateAdjacentClosingBraces;
